/* Bilingual event-based KP ranking and existing Vedic presentation. Natal calculations are unchanged. */
(()=>{'use strict';const $=id=>document.getElementById(id);
const purposes=[['money','धनप्राप्तीसाठी','For gaining wealth'],['health','आरोग्य व आजारातून बरे होण्यासाठी','For health and recovery from illness'],['marriage','विवाह व वैवाहिक सुखासाठी','For marriage and marital happiness'],['married-life','वैवाहिक जीवन आनंदी होण्यासाठी','For a happy married life'],['honour','मान-सन्मानासाठी','For honour and recognition'],['promotion','पदोन्नतीसाठी','For promotion'],['transfer','बदलीसाठी','For job transfer'],['lottery','लॉटरीत लाभ मिळवण्यासाठी','For lottery gains'],['job-interview','नोकरीच्या मुलाखतीत यशासाठी','For success in a job interview'],['education','शिक्षणात यशासाठी','For success in education'],['home','घरप्राप्तीसाठी','For acquiring a home'],['childbirth','संतानप्राप्तीसाठी','For childbirth'],['foreign-travel','परदेश प्रवासासाठी','For foreign travel'],['foreign-study','परदेशात शिक्षणासाठी','For education abroad'],['anger','रागावर नियंत्रणासाठी','For controlling anger'],['all-wishes','सर्व कार्यांत यश व इच्छापूर्तीसाठी','For success in all undertakings and fulfilment of wishes']];
const stones={Su:['सूर्य','Sun','माणिक','Ruby'],Mo:['चंद्र','Moon','मोती','Pearl'],Ma:['मंगळ','Mars','लाल पोवळे','Red coral'],Me:['बुध','Mercury','पाचू','Emerald'],Ju:['गुरु','Jupiter','पिवळा पुष्कराज','Yellow sapphire'],Ve:['शुक्र','Venus','हिरा','Diamond'],Sa:['शनी','Saturn','नीलम','Blue sapphire'],Ra:['राहू','Rahu','गोमेद','Hessonite'],Ke:['केतू','Ketu','वैडूर्य / लसण्या','Cat’s eye']};
const PRESETS={money:[[2,6,11],'Financial Position'],health:[[1,5,11],'Cure'],marriage:[[2,7,11],'Love Affair & Marriage'],'married-life':[[2,5,7,11],'MARRIED LIFE'],honour:[[10],'Prediction catalogue #61'],promotion:[[2,6,10,11],'Desired Job / Promotion'],transfer:[[3,10,12],'Prediction catalogue #1368'],lottery:[[2,6,11],'Prediction catalogue #831'],'job-interview':[[2,6,10,11],'Interview for Job'],education:[[4,9,11],'Education & Examination'],home:[[4,11,12],'Change of House'],childbirth:[[2,5,11],'Child Birth'],'foreign-travel':[[3,9,12],'Job in India or Abroad'],'foreign-study':[[3,9,12],'Going Abroad for Higher Studies'],anger:[[1,5,9],'मालकाने दिलेला नियम / Owner-approved houses 1,5,9'],'all-wishes':[[11],'KP: इच्छा-पूर्तीचा अकरावा भाव / XI house: fulfilment of desires']};
const RULE='KP नियम: प्रत्येक ग्रहाच्या कार्येश भावांपैकी निवडलेल्या घटनेशी संबंधित वेगवेगळे भाव मोजा. सर्वाधिक भाव दर्शवणाऱ्या ग्रहाचे रत्न निवडा; समान गुण असल्यास सर्व समान ग्रह दाखवा. / KP rule: count each planet’s unique relevant event houses. Recommend the gemstone of the planet with the highest count; show every tied leader.';
function ruleText(){const p=KPGemstoneEventRanking.housePolicy($('gem-event')?.value);return RULE+' वर्ज्य भाव / Blocking houses: '+p.excluded.join(', ')+(p.allowed.length?' · अपवाद / Allowed exception: '+p.allowed.join(', '):'')+'.';}
const VEDIC_RULE='वैदिक नियम: लग्नेश, पंचमेश व लाभेश — १, ५ आणि ११ भावांचे राशिस्वामी. / Vedic rule: Lagnesh, Panchamesh and Labhesh — sign lords of houses 1, 5 and 11.';
function force(){if($('gem-mode')&&!['kp','vedic'].includes($('gem-mode').value))$('gem-mode').value='kp';const select=$('gem-event');if(select&&!purposes.some(p=>p[0]===select.value))select.value='money';}
function rule(){return {mode:$('gem-mode').value,purpose:$('gem-event').value,method:'fourfold',required:$('gem-required').value,excluded:'',roles:['planet','star','sub'],stones:Object.fromEntries(Object.keys(stones).map(id=>[id,$('gem-stone-'+id)?.value||stones[id][3]]))};}
function paint(){if(!$('gem-results'))return;force();const mode=$('gem-mode'),selected=mode.value,vedic=selected==='vedic';if(mode.options.length!==2||!mode.querySelector('option[value=vedic]')){mode.replaceChildren(new Option('KP घटना-आधारित नियम / KP event-based rule','kp'),new Option('वैदिक नियम / Vedic rule','vedic'));mode.value=selected;}else{mode.options[0].textContent='KP घटना-आधारित नियम / KP event-based rule';mode.options[1].textContent='वैदिक नियम / Vedic rule';}mode.disabled=false;mode.closest('div').querySelector('label').textContent='नियम / Rule';$('gem-event').closest('div').querySelector('label').textContent='उद्देश निवडा / Select purpose';$('gem-event').closest('div').hidden=vedic;if($('gem-event-houses-wrap'))$('gem-event-houses-wrap').hidden=vedic;$('gem-event').disabled=vedic;const card=$('gemstones').querySelector('.gem-simple-card');card.dataset.noLocalize='true';card.querySelector('h2').textContent='KP / वैदिक रत्न मार्गदर्शन · KP / Vedic gemstone guidance';card.querySelector('.gem-rule-summary').textContent=vedic?VEDIC_RULE:ruleText();const guidance=card.querySelector('details');if(guidance)guidance.hidden=!vedic;$('gem-event-proof').textContent='स्रोत / Source: '+(PRESETS[$('gem-event').value]?.[1]||'स्वतः निवडलेले भाव / Entered houses')+' · संबंधित भाव / Relevant houses: '+$('gem-required').value;$('gem-event-proof').hidden=vedic;const headers=card.querySelectorAll('table thead th');['प्राधान्य / Priority','ग्रह / Planet','रत्न / Gemstone','कारण / Evidence'].forEach((text,i)=>{if(headers[i])headers[i].textContent=text;});try{const data=KPGemstones.evaluate(currentKPModel,rule());for(const row of data.results.filter(r=>r.qualifies)){const tr=$('gem-results').querySelector('[data-gem-planet="'+row.id+'"]');if(!tr)continue;const s=stones[row.id];tr.cells[1].textContent=s[0]+' / '+s[1];tr.cells[2].textContent=s[2]+' / '+s[3];tr.cells[3].textContent=vedic?'राशिस्वामित्वाचे भाव / Sign-owned houses: '+row.ownership.join(', '):row.score+'/'+data.required.length+' · संबंधित भाव / Matching houses: '+row.matched.join(', ')+' · सर्व कार्येश भाव / All signified houses: '+row.houses.join(', ');}const count=data.results.filter(r=>r.qualifies).length;$('gem-status').textContent=vedic?'वैदिक नियमानुसार पात्र रत्ने / Eligible gemstones under the Vedic rule: '+count:count?'सर्वाधिक संबंधित भाव दर्शवणारी रत्ने / Gemstones with maximum relevant houses: '+count+' · '+data.highest+'/'+data.required.length:'वर्ज्य भाव तपासल्यानंतर पात्र ग्रह आढळला नाही. / No eligible planet remains after checking the relevant and blocking houses.';}catch(e){$('gem-status').textContent=e.message;}}
function init(){const card=$('gemstones')?.querySelector('.gem-simple-card');if(!card)return;window.KPGemstoneDocument=Object.freeze({...window.KPGemstoneDocument,evaluate:KPGemstoneEventRanking.evaluate});const select=$('gem-event'),saved=select.value;select.replaceChildren(...purposes.map(([id,mr,en])=>new Option(mr+' / '+en,id)));select.value=purposes.some(p=>p[0]===saved)?saved:'money';$('gem-companion-panel')?.remove();$('gem-primary-panel-title')?.remove();const houses=$('gem-required'),label=document.createElement('label');label.id='gem-event-houses-wrap';label.textContent='संबंधित भाव / Relevant houses';houses.type='text';houses.placeholder='उदा. / e.g. 2,6,11';label.append(houses);card.querySelector('.gem-simple-actions').append(label);houses.value=(PRESETS[select.value]?.[0]||[]).join(',');force();const original=window.KPGemstones;window.KPGemstones=Object.freeze({...original,refresh(...args){force();const data=original.refresh(...args);paint();return data;},getData(){force();const data=original.getData();paint();return data;},snapshot(){force();const html=original.snapshot();paint();const box=document.createElement('div');box.innerHTML=html;const vedic=$('gem-mode').value==='vedic';if(!vedic)box.querySelector('.gem-ratna-guidance')?.remove();box.querySelector('.gem-report-heading h2').textContent=vedic?'वैदिक रत्न मार्गदर्शन / Vedic gemstone guidance':'KP घटना-आधारित रत्न मार्गदर्शन / KP event-based gemstone guidance';const purpose=box.querySelector('.gem-report-heading+p');if(purpose)purpose.textContent=vedic?'वैदिक नियम / Vedic rule':select.selectedOptions[0].textContent;const status=purpose?.nextElementSibling;if(status)status.textContent=$('gem-status').textContent;const table=box.querySelector('.gem-report-table');if(table)table.innerHTML=card.querySelector('table').innerHTML;const proof=box.querySelector('.gem-report-rule');if(proof)proof.textContent=vedic?VEDIC_RULE:ruleText();return box.innerHTML;}});const restore=window.restoreChartData;window.restoreChartData=function(...args){const result=restore.apply(this,args);force();KPGemstones.refresh();return result;};select.addEventListener('change',()=>{$('gem-required').value=(PRESETS[select.value]?.[0]||[]).join(',');KPGemstones.refresh();});$('gem-required').addEventListener('change',()=>KPGemstones.refresh());$('gem-mode').addEventListener('change',()=>KPGemstones.refresh());new MutationObserver(paint).observe($('gem-results'),{childList:true});window.addEventListener('kp-preferences-changed',paint);KPGemstones.refresh();}
window.KPOriginalGemstonePresentation=Object.freeze({purposes:()=>purposes.map(p=>({id:p[0],marathi:p[1],english:p[2]})),ruleText:RULE});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,150));else init();})();
